import {escapeHTML as e,filterIncidents,posture,paths,brief} from './logic.mjs';
let data,page='overview',selected='access',fixed=false;
const titles={overview:'Overview',incidents:'Incident investigation',lab:'API scenario replay',posture:'Cloud posture',rules:'Detection rules',evidence:'Engineering evidence'};
const ruleTitles={'ACCESS-001':'Cross-tenant access attempts','AUTH-001':'Repeated invalid authentication','RATE-001':'Request allowance exceeded','ADMIN-001':'Privileged incident change','EXPORT-001':'Unusual data retrieval'};
const ruleSpecs={'ACCESS-001':{threshold:3,kind:'access_denied',scope:'Verified tenant + subject'},'AUTH-001':{threshold:5,kind:'auth_failure',scope:'Unverified aggregate; no identity attribution'},'RATE-001':{threshold:1,kind:'rate_limited',scope:'Verified tenant + subject'},'ADMIN-001':{threshold:1,kind:'admin_action',scope:'Verified tenant + subject'},'EXPORT-001':{threshold:4,kind:'bulk_read',scope:'Verified tenant + subject'}};
const content=document.querySelector('#content');
const badge=(text,type='neutral')=>`<span class="badge ${e(type)}">${e(text)}</span>`;
const heading=(title,desc,action='')=>`<div class="page-head"><div><div class="eyebrow">SENTINELAPI / SECURITY OPERATIONS</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;
const panel=(title,body,extra='')=>`<section class="panel"><div class="panel-head"><h2>${title}</h2>${extra}</div><div class="panel-body">${body}</div></section>`;
const time=t=>new Date(t*1000).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'});
const stat=(label,value,note,icon='↗')=>`<div class="stat"><div class="stat-head">${label}<span class="mint">${icon}</span></div><strong>${value}</strong><small>${note}</small></div>`;
function incidentRows(items){return items.map(i=>`<tr class="clickable"><td><button class="link" data-incident="${e(i.id)}"><span class="cell-title">${e(ruleTitles[i.rule])}</span><span class="cell-sub">${e(i.rule)} · ${e(i.id.slice(0,8))}</span></button></td><td>${badge(i.severity,i.severity)}</td><td><span class="cell-title">${e(i.actor)}</span><span class="cell-sub">${e(i.tenant)}</span></td><td>${badge(i.status)}</td><td><button class="link" data-incident="${e(i.id)}">Investigate ↗</button></td></tr>`).join('');}
function incidentTable(items){return `<div class="table-wrap"><table><thead><tr><th>DETECTION</th><th>SEVERITY</th><th>IDENTITY / TENANT</th><th>CAPTURED STATUS</th><th>ACTION</th></tr></thead><tbody>${incidentRows(items)}</tbody></table>${items.length?'':'<div class="empty">No incidents match these filters.</div>'}</div>`;}
const orbit=`<svg viewBox="0 0 230 180" aria-hidden="true"><g fill="none" stroke="#365b4a"><circle cx="115" cy="90" r="74" stroke-dasharray="2 6"/><circle cx="115" cy="90" r="55"/><path d="M0 90h65m100 0h65M115 0v35m0 110v35"/></g><g class="ring"><circle cx="115" cy="16" r="4" fill="#85e5bf"/><circle cx="170" cy="138" r="3" fill="#f8b77a"/></g><path d="m115 52 29 12v24c0 18-14 29-29 37-15-8-29-19-29-37V64Z" fill="#244337" stroke="#85e5bf" stroke-width="1.5"/><path d="m103 88 9 9 17-22" stroke="#85e5bf" stroke-width="3" fill="none"/><text x="115" y="166" text-anchor="middle" fill="#769785" font-family="monospace" font-size="8" letter-spacing="2">VERIFY · DETECT · INVESTIGATE</text></svg>`;
function overview(){const counts={};for(const ev of data.events)counts[ev.kind]=(counts[ev.kind]||0)+1;const kinds=[['payment_read','Read'],['access_denied','Denied'],['auth_failure','Auth'],['bulk_read','Bulk'],['rate_limited','Rate'],['admin_action','Admin']];const max=Math.max(...Object.values(counts));return heading('Security, with evidence.','A working API security lab. Every alert connects to a rule, a request, and a reproducible test.',`<a class="button ghost" href="#evidence">View project evidence ↗</a>`)+`<section class="hero"><div class="hero-copy"><div class="eyebrow">BUILT TO VERIFY. DESIGNED TO EXPLAIN.</div><h2>From a suspicious API request<br>to an investigated incident.</h2><p>Follow a cross-tenant access attempt through identity validation, authorization, detection, and an auditable evidence trail.</p><a class="button primary" href="#lab">Explore the API replay <span>→</span></a><span class="pill" style="margin-left:15px">SYNTHETIC DATA ONLY</span></div><div class="hero-art">${orbit}</div></section><div class="stats">${stat('Security regression tests',data.tests.passed,'Passed in the recorded local run','✓')}${stat('Seeded rules detected',`${data.metrics.seeded_rules_detected}<span> / 5</span>`,'Five configured detection rules')}${stat('Benign sample alerts',data.metrics.benign_alerts,`${data.metrics.benign_requests} normal reads evaluated`,'◌')}${stat('Configuration findings',data.findings.length,'Sample cloud configuration','◇')}</div><div class="grid">${panel('Recorded API activity',`<div class="legend"><span><i></i>Application activity</span><span><i style="background:var(--orange)"></i>Blocked or invalid requests</span></div><div class="chart">${kinds.map(([key,label])=>`<div class="bar-group ${['access_denied','auth_failure','rate_limited'].includes(key)?'warn':''}"><small>${counts[key]||0}</small><div class="bar" style="height:${((counts[key]||0)/max)*100}px"></div><label>${label}</label></div>`).join('')}</div><p class="chart-note">${data.events.length} captured events · Local TestClient / SQLite · No live telemetry</p>`,`<small>RECORDED RUN</small>`)}${panel('Protection layers',`<div class="control"><span>RS256 signature & token claims</span><span class="check">✓ Tested</span></div><div class="control"><span>Object-level tenant authorization</span><span class="check">✓ Tested</span></div><div class="control"><span>Rate allowance & window recovery</span><span class="check">✓ Tested locally</span></div><div class="control"><span>Redacted audit evidence</span><span class="check">✓ Tested</span></div><div class="control"><span>Apigee / Keycloak / Docker</span>${badge('Adapters supplied')}</div>`)}</div><section class="panel"><div class="panel-head"><h2>Recorded incidents</h2><a href="#incidents" class="link">View all incidents →</a></div>${incidentTable(data.incidents.slice(0,4))}</section><div class="tags">${['Python / FastAPI','OAuth2 / JWT','Detection engineering','Tenant isolation','DevSecOps','Cloud posture'].map(x=>`<span class="tag">${x}</span>`).join('')}</div>`;}
function incidents(){return heading('Follow the evidence.','Inspect captured alerts, correlated events, and investigation guidance. Records remain read-only.')+`<div class="notice">These incidents were generated by the Python lab. “Investigating” is a captured test state; this viewer does not modify the backend.</div><section class="panel"><div class="panel-head"><h2>Incident queue <span class="muted">/ ${data.incidents.length}</span></h2><div class="filters"><input id="incident-search" type="search" placeholder="Search rule, actor, tenant…" aria-label="Search incidents"><select id="severity-filter" aria-label="Filter severity"><option value="all">All severities</option><option value="high">High</option><option value="medium">Medium</option><option value="low">Low</option></select></div></div><div id="incident-table">${incidentTable(data.incidents)}</div></section><div style="margin-top:22px">${panel('How to investigate',`<div class="steps"><div class="step"><span class="number">1</span><div><strong>Validate the detection</strong><p>Check the threshold, window, subject, and event references.</p></div></div><div class="step"><span class="number">2</span><div><strong>Establish context</strong><p>Compare the request with expected access and legitimate client behavior.</p></div></div><div class="step"><span class="number">3</span><div><strong>Confirm the control</strong><p>Review blocked responses and rerun the authorization regression test.</p></div></div></div>`)}</div>`;}
const scenarioNotes={benign:'A valid identity reads its own tenant’s payment. The request succeeds and creates an audit event without an alert.',access:'Alice is authenticated for tenant-a. She requests tenant-b’s payment three times. Object authorization returns 404 without disclosing the record; ACCESS-001 opens an incident.',auth:'Five invalid tokens produce 401 responses and an aggregate AUTH-001 alert. The lab cannot verify a tenant or subject for these requests.',export:'Four tenant-scoped list reads produce an EXPORT-001 alert. This is a simple volume rule, not proof of data theft.',admin:'An authorized analyst changes an incident to investigating. The action creates an audit event and an ADMIN-001 review alert.',rate:'The replay configures a two-request allowance. The third request returns 429 and triggers RATE-001.'};
function replayDetail(){const s=data.scenarios.find(s=>s.id===selected);const rule={access:'ACCESS-001',auth:'AUTH-001',export:'EXPORT-001',admin:'ADMIN-001',rate:'RATE-001'}[s.id];const incident=data.incidents.find(i=>i.rule===rule);return `<div class="eyebrow">CAPTURED PYTHON RESPONSE</div><h2>${e(s.title)}</h2><p style="font-size:12px">${e(scenarioNotes[s.id])}</p><div class="terminal"><div class="terminal-top"><i></i><i></i><i></i><span class="muted" style="margin-left:8px">sentinel / recorded request trace</span></div><span class="green">${e(s.method)}</span> ${e(s.path)}\n${s.responses.map((r,i)=>`\nrequest ${i+1} → <span class="${r.status>=400?'red':'green'}">HTTP ${r.status}</span>\n${e(JSON.stringify(r.body,null,2))}\ncorrelation: ${e(r.correlation)}`).join('\n')}</div><div class="control" style="margin:13px 0"><span class="muted">Recorded sequence duration</span><span class="mint" style="font-family:var(--mono)">${s.duration_ms} ms</span></div><p style="font-size:10px">Sequence duration includes local request handling. It is not a cloud benchmark or a detection-latency SLA.</p>${incident?`<button class="button primary" data-incident="${e(incident.id)}">Inspect resulting incident ↗</button>`:badge('No incident expected for this request')}`;}
function lab(){return heading('Replay the API boundary.','Explore captured requests from the running local lab. This page sends no attacks or API requests to external services.')+`<div class="notice">Recorded responses, real controls. Download the source to run these scenarios yourself against localhost.</div><div class="split">${panel('Choose a scenario',`<div class="lab-choice">${data.scenarios.map((s,i)=>`<button class="scenario ${s.id===selected?'active':''}" data-scenario="${s.id}" aria-pressed="${s.id===selected}"><span class="num">0${i+1}</span><span><strong>${e(s.title)}</strong><small>${e(s.method)} · ${s.requests} request${s.requests>1?'s':''}</small></span></button>`).join('')}</div>`)}<section class="panel"><div class="panel-body" id="replay-detail">${replayDetail()}</div></section></div><div style="margin-top:22px">${panel('Run the actual lab',`<div class="terminal"># Python 3.12+\nbash scripts/run_lab.sh\n\n# In another terminal: generate synthetic 15-minute tokens\n.venv/bin/python scripts/init_lab.py --tokens\n\n# Validate the controls\nPYTHONPATH=backend .venv/bin/pytest backend/tests -q</div><p style="margin-top:15px;font-size:11px">Open <code>http://127.0.0.1:8000/docs</code>, authorize with a local token, and inspect the APIs. Docker Compose adds PostgreSQL, Redis, and a gateway; that integration is supplied but was not executed here.</p><a class="button" href="assets/sentinel-api-source.zip" download>Download runnable source ↗</a>`)}</div>`;}
function currentAssets(){return data.assets.map(a=>fixed?{...a,public:false,permissions:(a.permissions||[]).filter(p=>p!=='*'),encrypted:true}:a);}
function postureDetail(){const a=currentAssets(),f=posture(a),p=paths(a);return `<div class="stats">${stat('Configuration findings',f.length,fixed?'After local fixture changes':'Before remediation')}${stat('High-priority findings',f.filter(x=>x.severity==='high').length,'Public exposure / excessive permissions')}${stat('Paths to sensitive data',p.length,'Explicit fixture relationships')}${stat('Live cloud connections','0','Read-only sample model','◇')}</div>${panel('Modeled path to a sensitive resource',p.length?`<div class="graph">${p[0].map((id,i)=>`<div class="node ${i===3?'danger':''}"><span class="node-icon">${['◎','⌘','◇','▤'][i]}</span><strong>${e(id)}</strong><small>${['Public origin','Public endpoint','Access relationship','Sensitive data'][i]}</small></div>`).join('')}</div><p style="font-size:11px;margin-bottom:0">Edges come from explicit <code>can_access</code> relationships in the supplied fixture. The model does not execute exploits or discover unknown permissions.</p>`:`<div class="empty"><span class="mint" style="font-size:24px">✓</span><h2 style="margin-top:12px">No modeled public path remains</h2><p>The browser fixture is now private with narrower permissions and encryption. This does not prove a real cloud environment is secure.</p></div>`,`<small>EDUCATIONAL GRAPH</small>`)}<section class="panel" style="margin-top:22px"><div class="panel-head"><h2>Configuration findings</h2>${badge(fixed?'Browser fixture changed':'Sample configuration')}</div><div class="table-wrap"><table><thead><tr><th>ASSET</th><th>FINDING</th><th>SEVERITY</th><th>RULE</th></tr></thead><tbody>${f.map(x=>`<tr><td>${e(x.asset)}</td><td>${e(x.reason)}</td><td>${badge(x.severity,x.severity)}</td><td class="cell-sub">${e(x.rule)}</td></tr>`).join('')}</tbody></table>${f.length?'':'<div class="empty">The three seeded configuration findings are resolved in this browser fixture.</div>'}</div></section>`;}
function cloud(){return heading('Understand the exposure.','Trace a supplied configuration from public access to sensitive data, then inspect the effect of remediation.',`<button class="button primary" id="fix-posture">${fixed?'Reset fixture':'Preview remediation'} ↗</button>`)+`<div class="notice amber">Educational configuration model. Remediation changes only the browser fixture. No cloud resources are read, provisioned, or modified.</div><div id="posture-detail">${postureDetail()}</div><div style="margin-top:22px">${panel('Remediation logic',`<div class="steps"><div class="step"><span class="number">1</span><div><strong>Remove public exposure</strong><p>Apply a private network boundary or explicitly justified ingress.</p></div></div><div class="step"><span class="number">2</span><div><strong>Narrow permissions</strong><p>Replace wildcard grants with the required resource-specific permissions.</p></div></div><div class="step"><span class="number">3</span><div><strong>Require encryption</strong><p>Confirm encryption settings and key access. The included Terraform example uses a private GCS bucket.</p></div></div></div>`)}</div>`;}
function rules(){return heading('Detection is a testable contract.','Five explainable rules, with evidence references, explicit thresholds, and documented blind spots.')+`<div class="rule-cards">${Object.entries(ruleSpecs).map(([id,s])=>{const i=data.incidents.find(x=>x.rule===id);return `<section class="panel rule-card"><div style="display:flex;justify-content:space-between">${badge(id)}${badge(i.severity,i.severity)}</div><h2>${ruleTitles[id]}</h2><p>${e(i.rationale)}</p><pre>event.kind = ${s.kind}\ncount ≥ ${s.threshold}\nwindow = 60 seconds\nscope = ${s.scope}</pre><p>${e(i.guidance)}</p><button class="link" data-incident="${e(i.id)}">Inspect rule evidence ↗</button><div class="rule-foot">VERSION 1.0.0 · PYTHON IMPLEMENTATION · SEE SOURCE FOR CONFIGURATION</div></section>`;}).join('')}</div><div class="notice amber" style="margin-top:22px">Rule limitations: failed tokens cannot establish identity; bulk reads may be legitimate; a rate alert can reflect retries; privileged actions are review signals. The ten-request benign sample is too small to estimate production false-positive rates.</div>`;}
const portfolioText='SentinelAPI — API Threat Detection & Cloud Security Lab\n\nBuilt a Python/FastAPI lab that validates RS256 JWTs, enforces tenant-level object authorization, records redacted audit events, and creates evidence-linked security incidents. Implemented five detection rules and automated security regression tests. Created an interactive dashboard that replays real local test responses and models attack paths from supplied cloud configuration. Included Docker Compose adapters for PostgreSQL, Redis, Nginx, and optional Keycloak, plus Apigee policy examples and DevSecOps workflows.\n\nThe hosted showcase uses synthetic recorded evidence. Cloud integrations and deployment adapters require separate environment validation.';
function evidence(){return heading('Show the engineering behind it.','Source, tests, assumptions, and limitations. Built for a reviewer who wants to verify the claims.',`<a class="button primary" href="assets/sentinel-api-source.zip" download>Download project ↗</a>`)+`<div class="stats">${stat('Regression tests passed',data.tests.passed,`${data.tests.failed} failures · ${data.tests.seconds}s local run`,'✓')}${stat('Detection rules exercised','5','Five positive seeded scenarios')}${stat('Benign requests evaluated','10','0 alerts in this small cohort')}${stat('Dependency audit',data.audit?.vulnerabilities??'—','Current scan; see report','✓')}</div><div class="evidence-list"><section class="panel evidence-item"><h3>Runnable Python security lab</h3><p>FastAPI, RS256 token verification, SQLAlchemy storage, tenant isolation, rate limiting, and evidence-linked incidents.</p><div class="coverage"><span>Implemented</span><span>Locally tested</span></div><a class="link" href="assets/sentinel-api-source.zip" download>Download complete source →</a></section><section class="panel evidence-item"><h3>Regression test report</h3><p>Positive and negative authorization tests, invalid token cases, tenant-scoped analyst access, evidence redaction, and detection windows.</p><div class="coverage"><span>${data.tests.passed} passed</span><span>${data.tests.failed} failed</span></div><a class="link" href="assets/test-results.xml" download>Download JUnit results →</a></section><section class="panel evidence-item"><h3>Captured scenario evidence</h3><p>Six request sequences with actual response codes, correlation IDs, event records, and resulting incidents.</p><div class="file">Generated: ${e(data.generated_at)}</div><a class="link" href="assets/replay.json" download>Download evidence JSON →</a></section><section class="panel evidence-item"><h3>Threat model & review guide</h3><p>Trust boundaries, security assumptions, control coverage, demonstration script, and platform-ready project descriptions.</p><a class="link" href="assets/project-guide.md" download>Download project guide →</a></section><section class="panel evidence-item"><h3>DevSecOps & supply chain</h3><p>Bandit static analysis and dependency audit were run locally. CI also declares secret scanning, container scanning, and SBOM generation.</p><a class="link" href="assets/dependency-audit.json" download>Download dependency audit →</a><br><a class="link" href="assets/static-analysis.json" download>Download static analysis →</a><br><a class="link" href="assets/sbom.cdx.json" download>Download Python SBOM →</a></section><section class="panel evidence-item"><h3>Integration adapters</h3><p>PostgreSQL, Redis, Nginx, optional Keycloak, Apigee policy examples, and private GCS Terraform. Supplied for further validation.</p>${badge('Not executed in external environments')}</section></div><div style="margin-top:22px">${panel('Architecture & trust boundaries',`<div class="graph"><div class="node"><span class="node-icon">⌘</span><strong>Lab client</strong><small>Synthetic bearer token</small></div><div class="node"><span class="node-icon">◇</span><strong>Identity boundary</strong><small>RS256 / claims / tenant</small></div><div class="node"><span class="node-icon">▤</span><strong>API & audit store</strong><small>Scope / limits / evidence</small></div><div class="node"><span class="node-icon">◈</span><strong>Analyst boundary</strong><small>Role + tenant scope</small></div></div><p style="font-size:11px">The hosted dashboard reads a static evidence export. The downloadable backend provides the actual enforcement and incident APIs. Admin tokens can review all tenants; analyst tokens remain tenant-scoped.</p>`)}</div><div class="split" style="margin-top:22px">${panel('Portfolio description',`<div class="copy-box">${e(portfolioText)}</div><button class="button" id="copy-portfolio" style="margin-top:15px">Copy project description ↗</button>`)}${panel('Implementation status',`<div class="text-content"><h3 style="margin-top:0">Implemented and tested locally</h3><ul><li>Signed-token authentication and tenant isolation</li><li>Five detection rules and incident evidence</li><li>Local rate limiting and audit redaction</li><li>Read-only replay and fixture posture model</li></ul><h3>Supplied, requiring integration validation</h3><ul><li>Docker, PostgreSQL, Redis, and Keycloak profiles</li><li>Apigee policies and Terraform deployment example</li><li>GitHub Actions container, secret, and SBOM jobs</li></ul><h3>Future work</h3><ul><li>Live cloud telemetry and deployed Apigee connection</li><li>Service-to-service mTLS and Kubernetes hardening</li><li>Optional model-backed investigation assistant</li></ul><p>The incident brief is deterministic and evidence-based. No AI model, automated remediation, or compliance certification is claimed.</p></div>`)}</div>`;}
function render(){page=location.hash.slice(1);if(!titles[page])page='overview';document.querySelector('#breadcrumb').textContent=titles[page];document.title=`${titles[page]} | SentinelAPI`;document.querySelectorAll('nav a').forEach(a=>a.dataset.page===page?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current'));content.innerHTML=({overview,incidents,lab,posture:cloud,rules,evidence}[page])();if(page==='incidents'){const refresh=()=>{document.querySelector('#incident-table').innerHTML=incidentTable(filterIncidents(data.incidents,document.querySelector('#incident-search').value,document.querySelector('#severity-filter').value));};document.querySelector('#incident-search').addEventListener('input',refresh);document.querySelector('#severity-filter').addEventListener('change',refresh);}document.querySelector('#fix-posture')?.addEventListener('click',()=>{fixed=!fixed;document.querySelector('#posture-detail').innerHTML=postureDetail();document.querySelector('#fix-posture').textContent=fixed?'Reset fixture ↗':'Preview remediation ↗';});document.querySelector('#copy-portfolio')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(portfolioText);toast('Project description copied');}catch{toast('Select the description text to copy it.');}});}
function showIncident(id){const i=data.incidents.find(i=>i.id===id);if(!i)return;const events=data.events.filter(ev=>i.evidence_ids.includes(ev.id)).sort((a,b)=>a.timestamp-b.timestamp);document.querySelector('#dialog-content').innerHTML=`<div class="eyebrow">INCIDENT / ${e(i.id.slice(0,8))}</div><h2 id="dialog-title">${e(ruleTitles[i.rule])}</h2><div class="dialog-meta">${badge(i.severity,i.severity)}${badge(i.status)}${badge(i.rule)}</div><p>${e(i.rationale)}</p><div class="control"><span class="muted">Verified identity / scope</span><strong>${e(i.actor)} / ${e(i.tenant)}</strong></div><div class="control"><span class="muted">Rule version</span><strong>${e(i.rule_version)}</strong></div><h3 style="margin-top:25px">Correlated evidence</h3>${events.map(ev=>`<div class="timeline-item"><small>${time(ev.timestamp)} · ${e(ev.kind)}</small><h3>${e(ev.detail.reason||ev.detail.resource||ev.detail.incident||'Recorded activity')}</h3><p>${e(ev.detail.count!==undefined?`Records read: ${ev.detail.count}`:ev.actor+' · '+ev.tenant)}</p><div class="evidence-id">Event: ${e(ev.id)}<br>Correlation: ${e(ev.correlation)}</div></div>`).join('')}<h3>Investigation guidance</h3><p>${e(i.guidance)}</p><button class="button primary" id="generate-brief">Generate evidence brief ↗</button><div id="brief-output" style="margin-top:15px"></div>`;document.querySelector('#generate-brief').addEventListener('click',()=>{const b=brief(i,data.events);document.querySelector('#brief-output').innerHTML=`<div class="brief"><strong>Evidence brief</strong><p>${e(b.text)}</p><small>${e(b.label)}</small><div class="evidence-id">References: ${b.references.map(e).join(', ')}</div></div>`;});document.querySelector('#incident-dialog').showModal();}
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('visible');setTimeout(()=>t.classList.remove('visible'),2500);}
document.querySelector('#dialog-close').addEventListener('click',()=>document.querySelector('#incident-dialog').close());document.querySelector('#incident-dialog').addEventListener('click',ev=>{if(ev.target===ev.currentTarget)ev.currentTarget.close();});content.addEventListener('click',ev=>{const incident=ev.target.closest('[data-incident]');if(incident)showIncident(incident.dataset.incident);const s=ev.target.closest('[data-scenario]');if(s){selected=s.dataset.scenario;document.querySelectorAll('[data-scenario]').forEach(b=>{const active=b.dataset.scenario===selected;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});document.querySelector('#replay-detail').innerHTML=replayDetail();}});window.addEventListener('hashchange',()=>{if(data){render();window.scrollTo({top:0,behavior:'instant'});}});
try{const response=await fetch('assets/replay.json');if(!response.ok)throw new Error('Evidence request failed');data=await response.json();document.querySelector('#incident-count').textContent=data.incidents.length;render();}catch(err){content.innerHTML='<div class="empty"><h1>Evidence could not load</h1><p>Reload the page or download the lab source to explore locally.</p><button class="button" id="reload">Reload evidence</button></div>';document.querySelector('#reload').addEventListener('click',()=>location.reload());}
